type pairP3x4 struct {
	aA P3x4LA
	bA P3x4RA
	aD P3x4LD
	bD P3x4RD
	aE P3x4LE
	bE P3x4RE
	aF P3x4LF
	bF P3x4RF
}

func inputsP3x4(raw [][2]rawValue) []pairP3x4 {
	out := make([]pairP3x4, len(raw))
	for n, rv := range raw {
		c := &out[n]
		switch rv[0].k {
		case 0:
			v := P3x4L0{X: rv[0].x}
			c.aA, c.aD, c.aE, c.aF = v, P3x4LD{1, v.X}, P3x4LE{1, v}, v
		case 1:
			v := P3x4L1{X: rv[0].x}
			c.aA, c.aD, c.aE, c.aF = v, P3x4LD{2, v.X}, P3x4LE{2, v}, v
		case 2:
			v := P3x4L2{X: rv[0].x}
			c.aA, c.aD, c.aE, c.aF = v, P3x4LD{3, v.X}, P3x4LE{3, v}, v
		}
		switch rv[1].k {
		case 0:
			v := P3x4R0{X: rv[1].x}
			c.bA, c.bD, c.bE, c.bF = v, P3x4RD{1, v.X}, P3x4RE{1, v}, v
		case 1:
			v := P3x4R1{X: rv[1].x}
			c.bA, c.bD, c.bE, c.bF = v, P3x4RD{2, v.X}, P3x4RE{2, v}, v
		case 2:
			v := P3x4R2{X: rv[1].x}
			c.bA, c.bD, c.bE, c.bF = v, P3x4RD{3, v.X}, P3x4RE{3, v}, v
		case 3:
			v := P3x4R3{X: rv[1].x}
			c.bA, c.bD, c.bE, c.bF = v, P3x4RD{4, v.X}, P3x4RE{4, v}, v
		}
	}
	return out
}

